#!/bin/bash
# The refresh_top proof pipeline from one export directory, outside the lake package.
#
# Usage: run.sh <export dir> <out dir> [adapt dir] [bridges dir]
#   <export dir>   the generated modules (Stage_*, Claim, Requirement_0, Backend, ... with facts)
#   <out dir>      the parameter directory written here: generated/ (copy of the export), the
#                  generic modules, adapters, bridges, every generated proof module, olean/, logs/
#   [adapt dir]    GenIface.lean, Gen_Stage_*_Scopes.lean and roles.json; when omitted they are
#                  generated by gen_adapters.py (from the template `generic/GenIface.lean`)
#   [bridges dir]  GenBridge_*.lean (default: the `generic/` copies)
# Environment:
#   GENFIX    directory whose top-level *.py files are overlaid on the generator copy (local
#             experiments only); default none
#   R         instance component period for gen_inst_certs (default 2)
#   JOBS      parallel Lean processes (default 2); MEM_GB per-process address space (default 20)
#   SKIP_BUILD=1  only generate (the summands then stay in their probe pass); KEEP=1 reuse
#             up-to-date oleans in the probe build (the final build always reuses them)
# Generator failures are logged (out/logs/gen_*.log) and listed in out/gen_status.txt; the build
# then skips the modules that need a missing file.
set -u
EXPORT=$(realpath "$1"); OUT=$(realpath -m "$2"); ADAPT=${3:-}; BRIDGES=${4:-}
HERE=$(cd "$(dirname "$0")" && pwd)
REPO=$(cd "$HERE/.." && pwd)
GENERIC_DIR=$REPO/generic
# Any refresh_top lake package provides the dependency oleans (Mathlib, the ir-core libraries).
W=$REPO/worst-n8-crt4x30
R=${R:-2}; JOBS=${JOBS:-2}; MEM_GB=${MEM_GB:-20}

mkdir -p "$OUT/generated" "$OUT/logs" "$OUT/olean"
cp -p "$EXPORT"/*.lean "$OUT/generated/"  # -p: KEEP=1 reuses the export oleans

# generator copy (so that a run records the generators it used)
rm -rf "$OUT/gen"; cp -r "$REPO/generator" "$OUT/gen"
if [ -n "${GENFIX:-}" ]; then
  for f in "$GENFIX"/*.py; do cp "$f" "$OUT/gen/"; echo "overlay $(basename "$f") from $GENFIX"; done
fi
GEN=$OUT/gen

# hand-written generic modules (parameter independent)
for f in "$GENERIC_DIR"/*.lean; do
  case $(basename "$f") in GenIface.lean|GenBridge_*) ;; *) cp -p "$f" "$OUT/";; esac
done
if [ -n "$BRIDGES" ]; then cp "$BRIDGES"/GenBridge_*.lean "$OUT/"; else cp -p "$GENERIC_DIR"/GenBridge_*.lean "$OUT/"; fi

: > "$OUT/gen_status.txt"
g() {  # g <name> <command...>: run one generator, log, record status
  local name=$1; shift
  "$@" > "$OUT/logs/gen_$name.log" 2>&1
  local rc=$?
  echo "$name exit=$rc" | tee -a "$OUT/gen_status.txt"
  [ $rc -ne 0 ] && tail -3 "$OUT/logs/gen_$name.log" | sed 's/^/    /'
  return 0
}
STAGES="Stage_preprocess Stage_encrypt Stage_online_eval"

# 1. roles and adapters
if [ -n "$ADAPT" ]; then
  cp "$ADAPT"/GenIface.lean "$ADAPT"/Gen_Stage_*_Scopes.lean "$ADAPT"/roles.json "$OUT/"
else
  cp "$GENERIC_DIR/GenIface.lean" "$OUT/GenIface.lean"  # template: its COMP section is regenerated
  g adapters python3 "$GEN/gen_adapters.py" "$OUT/generated" "$OUT" $STAGES Stage_decode --iface "$OUT/GenIface.lean"
  g roles python3 "$GEN/xroles.py" "$OUT/generated" --json "$OUT/roles.json"
fi
ROLES=$OUT/roles.json

# 2. instance pipeline (D, F)
g inst_certs     python3 "$GEN/gen_inst_certs.py" "$OUT/generated" "$OUT/Gen_InstCerts.lean" $STAGES --R "$R"
g instance       python3 "$GEN/gen_instance.py" "$OUT/generated" "$OUT" "$OUT" "$ROLES" $STAGES
g instance_pre   python3 "$GEN/gen_instance_pre.py" "$OUT/generated" "$OUT" "$OUT" "$ROLES"
g online_keys    python3 "$GEN/gen_instance_pre.py" "$OUT/generated" "$OUT" "$OUT" "$ROLES" Stage_online_eval
g online_smudge  python3 "$GEN/gen_online_smudge.py" "$OUT/generated" "$OUT/Gen_Online_Smudge.lean" "$OUT" "$ROLES"
g stage_links    python3 "$GEN/gen_stage_links.py" "$OUT/generated" "$OUT/Gen_Stage_Links.lean"
# 3.-4. decode loops, requirement facts
g decode_loops   python3 "$GEN/gen_decode_loops.py" "$OUT"
g requirement2   python3 "$GEN/gen_requirement2.py" "$OUT"
# 5. final combination, fresh/mask form, member values (G)
g final          python3 "$GEN/gen_final.py" "$OUT" --out "$OUT" --roles "$ROLES"
g online_fresh   python3 "$GEN/gen_online_fresh.py" "$OUT" --out "$OUT/Gen_Online_Fresh.lean" --roles "$ROLES"
g values         python3 "$GEN/gen_values.py" "$OUT" --roles "$ROLES" --out "$OUT/Gen_Online_Values.lean"
g wiring         python3 "$GEN/gen_wiring.py" "$OUT/generated" "$OUT" --out "$OUT/Gen_Wiring.lean"
# 6. part theorem, correctness
g inst_keys      python3 "$GEN/gen_inst_keys.py" "$OUT/generated" "$OUT" "$ROLES"
g part_ctx       python3 "$GEN/gen_part_ctx.py" "$OUT/generated" "$OUT/Gen_Part_Ctx.lean"
# The late generators read one another's output: the summands read `Gen_Part`, the source key
# equality (`gen_inst_cx`) reads the summands, and the key equalities and the part theorem read
# both. `late <summands args>` runs them in order; three rounds reach the fixed point from an
# empty directory.
late() {
  g summands     python3 "$GEN/gen_summands.py" "$OUT" --out "$OUT/Gen_Summands.lean" "$@"
  g inst_cx      python3 "$GEN/gen_inst_cx.py" "$OUT/generated" "$OUT" "$ROLES"
  g key_eq       python3 "$GEN/gen_key_eq.py" "$OUT/generated" "$OUT" "$ROLES"
  g part2        python3 "$GEN/gen_part2.py" "$OUT/generated" "$OUT/Gen_Part.lean" "$ROLES"
  g correct2     python3 "$GEN/gen_correct2.py" "$OUT" --part Gen_Part
}
# first pass: `--probe` makes every summand log its bounds' values per instance when built
for round in 1 2 3; do late --probe; done

if [ -n "${SKIP_BUILD:-}" ]; then
  mv -f "$OUT/Gen_Inst_Stage_online_eval_Chains.lean" "$OUT/Gen_Inst_Stage_online_eval_Chains.lean.test" 2>/dev/null || true
  exit 0
fi

# 7. build: the lake package's dependencies (not the toy's own generated oleans), then OUT
LP=$(cd "$W" && lake env printenv LEAN_PATH | tr ':' '\n' | grep -v "worst-n8-crt4x30" | paste -sd:)
LEAN=$(cd "$W" && lake env which lean)
build() { LEAN_PATH=$OUT/olean:$LP LEAN=$LEAN python3 "$HERE/build.py" "$OUT" --jobs "$JOBS" --mem-gb "$MEM_GB" "$@"; }

# 7a. probe build: the summand modules and their imports only (Gen_Summands does not import the
# chain test module, so it is not built), then the second pass with the probed closed bounds
build --only Gen_Summands ${KEEP:+--keep}
PROBE_LOGS=$(ls "$OUT"/logs/Gen_Summands_*Summand.log 2>/dev/null | paste -sd,)
if [ -n "$PROBE_LOGS" ]; then
  for round in 1 2 3; do late --bounds "$PROBE_LOGS"; done
else
  echo "summands_bounds exit=1 (no probe logs)" | tee -a "$OUT/gen_status.txt"
fi

# The chain theorems are test theorems (the part theorem inlines their steps); they are not built.
mv -f "$OUT/Gen_Inst_Stage_online_eval_Chains.lean" "$OUT/Gen_Inst_Stage_online_eval_Chains.lean.test" 2>/dev/null || true

# 7b. full build (the probe build's oleans are reused; the regenerated summand modules are rebuilt)
build --keep
